const CORS_HEADERS = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
  "Access-Control-Allow-Headers": "Content-Type, Authorization, X-TV-Remote"
};

function jsonResp(obj, status = 200) {
  return new Response(JSON.stringify(obj), {
    status,
    headers: {
      "Content-Type": "application/json; charset=utf-8",
      "Cache-Control": "no-store",
      ...CORS_HEADERS
    }
  });
}

async function sha256Hex(input) {
  const bytes = new TextEncoder().encode(input);
  const digest = await crypto.subtle.digest("SHA-256", bytes);
  return Array.from(new Uint8Array(digest)).map(b => b.toString(16).padStart(2, "0")).join("");
}

function randomToken() {
  const arr = new Uint8Array(24);
  crypto.getRandomValues(arr);
  return Array.from(arr).map(b => b.toString(16).padStart(2, "0")).join("");
}

function deterministicCode(deviceId) {
  if (deviceId === "50a009620752") return "500962";
  if (deviceId === "tablet01") return "160101";
  let hash = 2166136261;
  for (let i = 0; i < deviceId.length; i++) {
    hash ^= deviceId.charCodeAt(i);
    hash = Math.imul(hash, 16777619) & 0x7fffffff;
  }
  const num = 100000 + (hash % 900000);
  return String(num).padStart(6, "0");
}

let dbInitialized = false;
async function ensureDb(db) {
  if (!db || dbInitialized) return;
  await db.batch([
    db.prepare(`CREATE TABLE IF NOT EXISTS users (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      username TEXT NOT NULL UNIQUE COLLATE NOCASE,
      password_hash TEXT NOT NULL,
      display_name TEXT NOT NULL DEFAULT 'Bố Mẹ',
      default_pin TEXT NOT NULL DEFAULT '1601',
      created_at INTEGER NOT NULL
    )`),
    db.prepare(`CREATE TABLE IF NOT EXISTS sessions (
      token TEXT PRIMARY KEY,
      user_id INTEGER NOT NULL,
      created_at INTEGER NOT NULL,
      expires_at INTEGER NOT NULL
    )`),
    db.prepare(`CREATE TABLE IF NOT EXISTS devices (
      device_id TEXT PRIMARY KEY,
      pairing_code TEXT NOT NULL UNIQUE,
      owner_user_id INTEGER,
      device_name TEXT NOT NULL,
      device_type TEXT NOT NULL DEFAULT 'tablet',
      app_flavor TEXT NOT NULL DEFAULT 'guard',
      model TEXT NOT NULL DEFAULT '',
      pin_code TEXT NOT NULL DEFAULT '1601',
      last_seen_at INTEGER NOT NULL DEFAULT 0,
      created_at INTEGER NOT NULL DEFAULT 0
    )`),
    db.prepare(`INSERT OR IGNORE INTO devices (device_id, pairing_code, owner_user_id, device_name, device_type, app_flavor, model, pin_code, last_seen_at, created_at)
      VALUES ('50a009620752', '500962', NULL, 'Tivi Mi TV 4A', 'tv', 'launcher', 'Mi TV 4A', '1601', ?1, ?1)`).bind(Date.now()),
    db.prepare(`INSERT OR IGNORE INTO devices (device_id, pairing_code, owner_user_id, device_name, device_type, app_flavor, model, pin_code, last_seen_at, created_at)
      VALUES ('tablet01', '160101', NULL, 'Máy Tính Bảng Fire HD 10', 'tablet', 'guard', 'Fire HD 10', '1601', ?1, ?1)`).bind(Date.now())
  ]);
  dbInitialized = true;
}

async function listDevicesForUser(db, userId) {
  const { results } = await db.prepare(
    `SELECT device_id AS deviceId, pairing_code AS pairingCode, device_name AS deviceName,
            device_type AS deviceType, app_flavor AS appFlavor, model, pin_code AS pinCode, last_seen_at AS lastSeenAt
     FROM devices WHERE owner_user_id = ?1 ORDER BY created_at ASC`
  ).bind(userId).all();
  return results || [];
}

async function getAuthenticatedUser(request, db) {
  const auth = request.headers.get("Authorization") || "";
  let token = "";
  if (auth.startsWith("Bearer ")) {
    token = auth.slice(7).trim();
  } else {
    const u = new URL(request.url);
    token = (u.searchParams.get("token") || "").trim();
  }
  if (!token) return null;
  const row = await db.prepare(
    `SELECT u.id, u.username, u.display_name AS displayName, u.default_pin AS defaultPin, s.expires_at AS expiresAt
     FROM sessions s JOIN users u ON s.user_id = u.id
     WHERE s.token = ?1`
  ).bind(token).first();
  if (!row || row.expiresAt < Date.now()) return null;
  return { id: row.id, username: row.username, displayName: row.displayName, defaultPin: row.defaultPin, token };
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    const path = url.pathname;

    if (request.method === "OPTIONS") {
      return new Response(null, { status: 204, headers: CORS_HEADERS });
    }

    if (path === "/tablet.apk" || path === "/apk" || path === "/tqd-tablet-guard.apk" || path === "/download/guard.apk") {
      return Response.redirect("https://raw.githubusercontent.com/abm-dungtq/tqd-tv/main/releases/tqd-tablet-guard.apk", 302);
    }
    if (path === "/tv.apk" || path === "/tqd-tv-launcher.apk" || path === "/download/tv-launcher.apk") {
      return Response.redirect("https://raw.githubusercontent.com/abm-dungtq/tqd-tv/main/releases/tqd-tv-launcher-android6.apk", 302);
    }
    if (path === "/huongdan.html" || path === "/huongdan" || path === "/guide") {
      return new Response(HUONGDAN_PAGE, {
        headers: {
          "Content-Type": "text/html; charset=utf-8",
          "Cache-Control": "public, max-age=300"
        }
      });
    }

    const db = env && env.tqd_parental_db;
    if (path.startsWith("/api/") && db) {
      try {
        await ensureDb(db);

        // 1. POST /api/auth/register
        if (path === "/api/auth/register" && request.method === "POST") {
          const body = await request.json();
          const username = String(body.username || "").trim().toLowerCase();
          const password = String(body.password || "").trim();
          const displayName = String(body.displayName || "Bố Mẹ").trim() || "Bố Mẹ";
          const defaultPin = /^\d{4,6}$/.test(String(body.defaultPin || "").trim()) ? String(body.defaultPin).trim() : "1601";
          const pairingCode = String(body.pairingCode || "").replace(/\D/g, "");

          if (username.length < 3) {
            return jsonResp({ ok: false, error: "Tên đăng nhập phải có ít nhất 3 ký tự" }, 400);
          }
          if (password.length < 4) {
            return jsonResp({ ok: false, error: "Mật khẩu phải có ít nhất 4 ký tự" }, 400);
          }

          const existing = await db.prepare("SELECT id FROM users WHERE username = ?1").bind(username).first();
          if (existing) {
            return jsonResp({ ok: false, error: "Tên tài khoản này đã được đăng ký, vui lòng đăng nhập hoặc chọn tên khác!" }, 409);
          }

          const countRow = await db.prepare("SELECT COUNT(*) AS cnt FROM users").first();
          const isFirstUser = !countRow || Number(countRow.cnt) === 0;

          const passHash = await sha256Hex("tqd_salt_v1:" + username + ":" + password);
          const now = Date.now();
          const ins = await db.prepare(
            "INSERT INTO users (username, password_hash, display_name, default_pin, created_at) VALUES (?1, ?2, ?3, ?4, ?5)"
          ).bind(username, passHash, displayName, defaultPin, now).run();
          const userId = ins.meta.last_row_id;

          if (isFirstUser || username === "dungtq" || username === "admin") {
            await db.prepare(
              "UPDATE devices SET owner_user_id = ?1, pin_code = ?2 WHERE owner_user_id IS NULL AND device_id IN ('50a009620752', 'tablet01')"
            ).bind(userId, defaultPin).run();
          }

          let pairedDevice = null;
          if (pairingCode.length === 6) {
            let devRow = await db.prepare("SELECT * FROM devices WHERE pairing_code = ?1").bind(pairingCode).first();
            if (!devRow && body.fallbackDeviceId) {
              const fbId = String(body.fallbackDeviceId).trim();
              const fbType = body.fallbackDeviceType === "tv" ? "tv" : "tablet";
              const fbModel = String(body.fallbackModel || (fbType === "tv" ? "Android TV" : "Máy tính bảng")).trim();
              await db.prepare(
                `INSERT OR IGNORE INTO devices (device_id, pairing_code, owner_user_id, device_name, device_type, app_flavor, model, pin_code, last_seen_at, created_at)
                 VALUES (?1, ?2, ?3, ?4, ?5, 'guard', ?6, ?7, ?8, ?8)`
              ).bind(fbId, pairingCode, userId, fbModel, fbType, fbModel, defaultPin, now).run();
            } else if (devRow) {
              await db.prepare(
                "UPDATE devices SET owner_user_id = ?1, pin_code = ?2, last_seen_at = ?3 WHERE pairing_code = ?4"
              ).bind(userId, defaultPin, now, pairingCode).run();
            }
            pairedDevice = await db.prepare(
              "SELECT device_id AS deviceId, pairing_code AS pairingCode, device_name AS deviceName, device_type AS deviceType, app_flavor AS appFlavor, model FROM devices WHERE pairing_code = ?1"
            ).bind(pairingCode).first();
          }

          const token = randomToken();
          await db.prepare(
            "INSERT INTO sessions (token, user_id, created_at, expires_at) VALUES (?1, ?2, ?3, ?4)"
          ).bind(token, userId, now, now + 90 * 86400 * 1000).run();

          const devices = await listDevicesForUser(db, userId);
          return jsonResp({
            ok: true,
            token,
            user: { id: userId, username, displayName, defaultPin },
            pairedDevice,
            devices
          });
        }

        // 2. POST /api/auth/login
        if (path === "/api/auth/login" && request.method === "POST") {
          const body = await request.json();
          const username = String(body.username || "").trim().toLowerCase();
          const password = String(body.password || "").trim();
          const passHash = await sha256Hex("tqd_salt_v1:" + username + ":" + password);

          const userRow = await db.prepare(
            "SELECT id, username, display_name AS displayName, default_pin AS defaultPin FROM users WHERE username = ?1 AND password_hash = ?2"
          ).bind(username, passHash).first();
          if (!userRow) {
            return jsonResp({ ok: false, error: "Sai tên đăng nhập hoặc mật khẩu!" }, 401);
          }

          const now = Date.now();
          const token = randomToken();
          await db.prepare(
            "INSERT INTO sessions (token, user_id, created_at, expires_at) VALUES (?1, ?2, ?3, ?4)"
          ).bind(token, userRow.id, now, now + 90 * 86400 * 1000).run();

          const devices = await listDevicesForUser(db, userRow.id);
          return jsonResp({
            ok: true,
            token,
            user: userRow,
            devices
          });
        }

        // 3. POST /api/auth/logout
        if (path === "/api/auth/logout" && request.method === "POST") {
          const user = await getAuthenticatedUser(request, db);
          if (user && user.token) {
            await db.prepare("DELETE FROM sessions WHERE token = ?1").bind(user.token).run();
          }
          return jsonResp({ ok: true });
        }

        // 4. GET /api/me
        if (path === "/api/me" && request.method === "GET") {
          const user = await getAuthenticatedUser(request, db);
          if (!user) {
            return jsonResp({ ok: false, error: "unauthorized" }, 401);
          }
          const devices = await listDevicesForUser(db, user.id);
          return jsonResp({ ok: true, user, devices });
        }

        // 5. POST /api/device/register-code (Called by Android TV / Tablet App)
        if (path === "/api/device/register-code" && request.method === "POST") {
          const body = await request.json();
          const deviceId = String(body.deviceId || "").trim();
          if (!deviceId) {
            return jsonResp({ ok: false, error: "missing_deviceId" }, 400);
          }
          let reqCode = String(body.pairingCode || "").replace(/\D/g, "");
          if (reqCode.length !== 6) {
            reqCode = deterministicCode(deviceId);
          }
          const devType = body.deviceType === "tv" ? "tv" : "tablet";
          const appFlavor = body.appFlavor === "launcher" ? "launcher" : "guard";
          const model = String(body.model || (devType === "tv" ? "Android TV" : "Máy tính bảng")).trim();
          const legacyId = String(body.legacyId || "").trim();
          const now = Date.now();

          let row = await db.prepare("SELECT * FROM devices WHERE device_id = ?1").bind(deviceId).first();
          if (!row) {
            let inheritedOwner = null;
            let inheritedPin = "1601";
            if (legacyId) {
              const legRow = await db.prepare("SELECT * FROM devices WHERE device_id = ?1").bind(legacyId).first();
              if (legRow && legRow.owner_user_id) {
                inheritedOwner = legRow.owner_user_id;
                inheritedPin = legRow.pin_code || "1601";
              }
            }
            const codeConflict = await db.prepare("SELECT device_id FROM devices WHERE pairing_code = ?1").bind(reqCode).first();
            if (codeConflict && codeConflict.device_id !== deviceId) {
              reqCode = String(100000 + (Math.floor(Math.random() * 899999))).padStart(6, "0");
            }
            const defaultName = devType === "tv" ? ("Tivi " + model) : ("Máy tính bảng " + model);
            await db.prepare(
              `INSERT INTO devices (device_id, pairing_code, owner_user_id, device_name, device_type, app_flavor, model, pin_code, last_seen_at, created_at)
               VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, ?8, ?9, ?9)`
            ).bind(deviceId, reqCode, inheritedOwner, defaultName, devType, appFlavor, model, inheritedPin, now).run();
            row = await db.prepare("SELECT * FROM devices WHERE device_id = ?1").bind(deviceId).first();
          } else {
            await db.prepare(
              "UPDATE devices SET device_type = ?1, app_flavor = ?2, model = ?3, last_seen_at = ?4 WHERE device_id = ?5"
            ).bind(devType, appFlavor, model, now, deviceId).run();
          }

          let ownerName = "";
          if (row && row.owner_user_id) {
            const ownerRow = await db.prepare("SELECT display_name FROM users WHERE id = ?1").bind(row.owner_user_id).first();
            if (ownerRow) ownerName = ownerRow.display_name;
          }

          return jsonResp({
            ok: true,
            deviceId: row.device_id,
            pairingCode: row.pairing_code,
            paired: !!(row && row.owner_user_id),
            ownerName,
            deviceName: row ? row.device_name : model,
            pinCode: row ? row.pin_code : "1601"
          });
        }

        // 6. GET /api/device/pair-status
        if (path === "/api/device/pair-status" && request.method === "GET") {
          const deviceId = (url.searchParams.get("deviceId") || "").trim();
          const code = (url.searchParams.get("pairingCode") || "").trim();
          const row = deviceId
            ? await db.prepare("SELECT * FROM devices WHERE device_id = ?1").bind(deviceId).first()
            : await db.prepare("SELECT * FROM devices WHERE pairing_code = ?1").bind(code).first();
          if (!row) {
            return jsonResp({ ok: false, paired: false });
          }
          let ownerName = "";
          if (row.owner_user_id) {
            const ownerRow = await db.prepare("SELECT display_name FROM users WHERE id = ?1").bind(row.owner_user_id).first();
            if (ownerRow) ownerName = ownerRow.display_name;
          }
          return jsonResp({
            ok: true,
            deviceId: row.device_id,
            pairingCode: row.pairing_code,
            paired: !!row.owner_user_id,
            ownerName,
            deviceName: row.device_name,
            pinCode: row.pin_code
          });
        }

        // 7. POST /api/devices/pair (Parent enters 6-digit code on Web)
        if (path === "/api/devices/pair" && request.method === "POST") {
          const user = await getAuthenticatedUser(request, db);
          if (!user) {
            return jsonResp({ ok: false, error: "Vui lòng đăng nhập lại!" }, 401);
          }
          const body = await request.json();
          const code = String(body.pairingCode || "").replace(/\D/g, "");
          if (code.length !== 6) {
            return jsonResp({ ok: false, error: "Mã ghép nối phải gồm đúng 6 chữ số!" }, 400);
          }
          const customName = String(body.deviceName || "").trim();
          const customType = body.deviceType === "tv" ? "tv" : (body.deviceType === "tablet" ? "tablet" : "");
          const now = Date.now();

          let row = await db.prepare("SELECT * FROM devices WHERE pairing_code = ?1").bind(code).first();
          if (!row && body.fallbackDeviceId) {
            const fbId = String(body.fallbackDeviceId).trim();
            const fbType = customType || "tablet";
            const fbFlavor = body.fallbackAppFlavor === "launcher" ? "launcher" : "guard";
            const fbModel = String(body.fallbackModel || (fbType === "tv" ? "Android TV" : "Máy tính bảng")).trim();
            const fbName = customName || (fbType === "tv" ? ("Tivi " + fbModel) : ("Máy tính bảng " + fbModel));
            await db.prepare(
              `INSERT OR REPLACE INTO devices (device_id, pairing_code, owner_user_id, device_name, device_type, app_flavor, model, pin_code, last_seen_at, created_at)
               VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, ?8, ?9, ?9)`
            ).bind(fbId, code, user.id, fbName, fbType, fbFlavor, fbModel, user.defaultPin, now).run();
            row = await db.prepare("SELECT * FROM devices WHERE pairing_code = ?1").bind(code).first();
          }

          if (!row) {
            return jsonResp({
              ok: false,
              error: "Chưa tìm thấy thiết bị mang mã " + code + ". Hãy mở ứng dụng TQD KidGuard trên TV/Máy tính bảng và kiểm tra kết nối mạng!"
            }, 404);
          }

          const finalName = customName || row.device_name || row.model || "Thiết bị của con";
          const finalType = customType || row.device_type || "tablet";
          await db.prepare(
            "UPDATE devices SET owner_user_id = ?1, device_name = ?2, device_type = ?3, pin_code = ?4, last_seen_at = ?5 WHERE device_id = ?6"
          ).bind(user.id, finalName, finalType, user.defaultPin, now, row.device_id).run();

          const pairedDevice = await db.prepare(
            `SELECT device_id AS deviceId, pairing_code AS pairingCode, device_name AS deviceName,
                    device_type AS deviceType, app_flavor AS appFlavor, model, pin_code AS pinCode
             FROM devices WHERE device_id = ?1`
          ).bind(row.device_id).first();
          const devices = await listDevicesForUser(db, user.id);
          return jsonResp({ ok: true, pairedDevice, devices });
        }

        // 8. POST /api/devices/update
        if (path === "/api/devices/update" && request.method === "POST") {
          const user = await getAuthenticatedUser(request, db);
          if (!user) return jsonResp({ ok: false, error: "unauthorized" }, 401);
          const body = await request.json();
          if (body.defaultPin && /^\d{4,6}$/.test(String(body.defaultPin).trim())) {
            const cleanPin = String(body.defaultPin).trim();
            await db.batch([
              db.prepare("UPDATE users SET default_pin = ?1 WHERE id = ?2").bind(cleanPin, user.id),
              db.prepare("UPDATE devices SET pin_code = ?1 WHERE owner_user_id = ?2").bind(cleanPin, user.id)
            ]);
          }
          if (body.deviceId) {
            const devId = String(body.deviceId).trim();
            const devRow = await db.prepare("SELECT * FROM devices WHERE device_id = ?1 AND owner_user_id = ?2").bind(devId, user.id).first();
            if (devRow) {
              const nm = String(body.deviceName || devRow.device_name).trim();
              const fl = body.appFlavor === "launcher" ? "launcher" : (body.appFlavor === "guard" ? "guard" : devRow.app_flavor);
              await db.prepare("UPDATE devices SET device_name = ?1, app_flavor = ?2 WHERE device_id = ?3").bind(nm, fl, devId).run();
            }
          }
          const devices = await listDevicesForUser(db, user.id);
          return jsonResp({ ok: true, devices });
        }

        // 9. POST /api/devices/unpair
        if (path === "/api/devices/unpair" && request.method === "POST") {
          const user = await getAuthenticatedUser(request, db);
          if (!user) return jsonResp({ ok: false, error: "unauthorized" }, 401);
          const body = await request.json();
          const devId = String(body.deviceId || "").trim();
          if (devId) {
            await db.prepare("UPDATE devices SET owner_user_id = NULL WHERE device_id = ?1 AND owner_user_id = ?2").bind(devId, user.id).run();
          }
          const devices = await listDevicesForUser(db, user.id);
          return jsonResp({ ok: true, devices });
        }
      } catch (err) {
        return jsonResp({ ok: false, error: String(err && err.message ? err.message : err) }, 500);
      }
    }

    return new Response(HTML_PAGE, {
      headers: {
        "Content-Type": "text/html; charset=utf-8",
        "Cache-Control": "no-store, max-age=0"
      }
    });
  }
};
